#define ITEM_TO_BLOCK_STATE_COUNT 1014


static int minecraft_item_from_block_state(int block_state_id)
{
    int left = 0;
    int right = BLOCK_STATE_TO_ITEM_COUNT - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;
        int current = block_state_to_item[mid].block_state_id;

        if (current == block_state_id) {
            return block_state_to_item[mid].item_id;
        }

        if (current < block_state_id) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return 0;
}


static int minecraft_block_state_from_item(int item_id)
{
    int left = 0;
    int right = ITEM_TO_BLOCK_STATE_COUNT - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;
        int current = item_to_block_state[mid].item_id;

        if (current == item_id) {
            return item_to_block_state[mid].block_state_id;
        }

        if (current < item_id) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return 0;
}
#endif
